  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "AF-DX384, the closest structural analogue sharing the same pyrido-benzodiazepinone core and an acyl substituent on the ring nitrogen, is reported to have low BBB penetration that impeded its use in PET imaging, directly supporting poor CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "GW441756, a related pyrido-fused lactam, rapidly entered rat brain with an SUV of about 2, showing that the core lactam is not intrinsically impermeable; however, the query's polar N-methylpiperazine-acetyl side chain makes this permeable phenotype less transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "An N-methylpiperazine-containing heteroaromatic compound showed a brain-to-plasma AUC ratio of 4.9 in rats, demonstrating that N-methylpiperazine alone does not preclude brain penetration; the query's more polar, amide-rich scaffold is less favorable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "WAY100635, a piperazine amide, showed good maximal brain uptake in cynomolgus monkeys despite being a P-gp substrate, indicating that efflux liability alone is not decisive; the query is more hydrophilic and structurally closer to the peripherally selective AF-DX384 series.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is pirenzepine, a peripherally selective muscarinic antagonist known to have poor blood-brain barrier penetration. The closest analogue AF-DX384, sharing the same pyrido-benzodiazepinone core, is reported to have low BBB penetration. Although some related piperazine/amide compounds are brain-penetrant, the query's polar, amide-rich scaffold and direct analogue evidence outweigh these, predicting inadequate CNS access.",
  "evidence_gaps": [
    "No direct quantitative brain/plasma or CSF measurement for the query itself is present in the provided evidence.",
    "The closest analogue evidence is qualitative and does not specify the mechanism (e.g., passive permeability vs. efflux).",
    "Species differences and transporter status for the query are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

